#include <iostream>
#include <iomanip>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;

    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    // 初值取第一个元素，而不是 0：
    // 如果数据全是负数，从 0 开始找最大值会永远得到 0
    int mx = a[0];
    int mn = a[0];
    long long sum = 0;

    for (int i = 0; i < n; ++i) {
        if (a[i] > mx) mx = a[i];
        if (a[i] < mn) mn = a[i];
        sum += a[i];
    }

    // sum / n 是整数除法，小数直接被丢掉；乘 1.0 把运算拉进浮点数世界
    double avg = sum * 1.0 / n;

    cout << mx << endl;
    cout << mn << endl;
    cout << fixed << setprecision(2) << avg << endl;
    return 0;
}

