#include <iostream>
#include <vector>
using namespace std;

// 判断 n 是不是素数
bool isPrime(int n) {
    if (n < 2) return false;        // 0、1 和负数都不是素数
    if (n == 2) return true;        // 2 是唯一的偶素数，要单独放行
    if (n % 2 == 0) return false;   // 其余偶数一定有因子 2

    // 只需试除到根号 n：若 n = p * q 且 p <= q，则 p 一定不超过根号 n。
    // 写成 i * i <= n 而不是 i <= sqrt(n)，既不用引 <cmath>，也没有浮点误差
    for (int i = 3; i * i <= n; i += 2) {
        if (n % i == 0) return false;
    }
    return true;
}

int main() {
    int a, b;
    cin >> a >> b;

    // 不确定有几个素数，用 vector 边找边追加，它会自己增长
    vector<int> primes;
    for (int x = a; x <= b; ++x) {
        if (isPrime(x)) primes.push_back(x);
    }

    cout << primes.size() << endl;

    // 一个素数都没有时，题目要求只输出第一行
    if (!primes.empty()) {
        for (size_t i = 0; i < primes.size(); ++i) {
            if (i > 0) cout << " ";   // 用「前面再加空格」的办法避免行尾多出空格
            cout << primes[i];
        }
        cout << endl;
    }
    return 0;
}

