#include <iostream>
#include <string>
#include <cctype>
using namespace std;

int main() {
    string s;
    // cin >> s 会在空白字符处停下，空格就读不到了；
    // getline 一直读到换行，整行（含空格）都能拿到
    getline(cin, s);

    int letters = 0, digits = 0, spaces = 0, others = 0;

    // 范围 for：依次取出每个字符。这里只需要读，不需要改，所以用值拷贝 char c 就够
    for (char c : s) {
        // <cctype> 的函数要求参数是 unsigned char。
        // 若 char 是有符号的，值大于 127 的字符会变成负数，直接传进去是未定义行为
        unsigned char u = static_cast<unsigned char>(c);

        if (isalpha(u)) {
            ++letters;
        } else if (isdigit(u)) {
            ++digits;
        } else if (isspace(u)) {
            ++spaces;
        } else {
            ++others;
        }
    }

    cout << letters << endl;
    cout << digits << endl;
    cout << spaces << endl;
    cout << others << endl;
    return 0;
}

