#include <iostream>
#include <string>
#include <map>
using namespace std;

int main() {
    int n;
    cin >> n;

    // key = 单词，value = 出现次数。
    // map 内部是一棵按 key 排好序的平衡树，所以遍历出来天然就是字典序
    map<string, int> cnt;

    for (int i = 0; i < n; ++i) {
        string w;
        cin >> w;   // cin >> 会自动跳过空格和换行，正好一个词一个词地读
        // 如果 w 是第一次出现，operator[] 会自动插入一项并把值初始化为 0，再自增成 1
        cnt[w]++;
    }

    // const auto& 用引用绑定，避免每个元素都拷贝一份字符串
    for (const auto& kv : cnt) {
        cout << kv.first << " " << kv.second << endl;
    }
    return 0;
}

