#include <iostream>
using namespace std;

class Calculator {
public:
    // 成员函数后面的 const 表示「这个函数不修改对象的状态」。
    // 纯计算的函数都该加上，编译器还会帮你检查有没有误改成员
    long long add(long long a, long long b) const { return a + b; }
    long long sub(long long a, long long b) const { return a - b; }
    long long mul(long long a, long long b) const { return a * b; }

    // 除法有「除数为 0」这种失败情况：返回值用 bool 报告成功与否，
    // 真正的结果通过引用参数 result 带回去（引用是变量的别名，改它等于改外面的变量）
    bool div(long long a, long long b, long long& result) const {
        if (b == 0) return false;   // 整数除以 0 会让程序直接崩溃，必须先拦下来
        result = a / b;             // C++ 整数除法向零取整，-7 / 2 得到 -3
        return true;
    }
};

int main() {
    int q;
    cin >> q;

    Calculator calc;   // 类里没写构造函数时，编译器会自动生成一个

    for (int i = 0; i < q; ++i) {
        long long a, b;
        char op;
        cin >> a >> op >> b;   // cin 会自动跳过数字和运算符之间的空格

        long long r = 0;
        bool ok = true;

        switch (op) {
            case '+': r = calc.add(a, b); break;
            case '-': r = calc.sub(a, b); break;
            case '*': r = calc.mul(a, b); break;
            case '/': ok = calc.div(a, b, r); break;
            default:  ok = false; break;   // 题目保证不会出现其它符号
        }

        if (ok) {
            cout << r << endl;
        } else {
            cout << "error" << endl;
        }
    }
    return 0;
}

