if (calc.div(7, 2, r)) cout << r << endl;        // 输出 3
if (!calc.div(8, 0, r)) cout << "error" << endl; // 输出 error

cout << -7 / 2 << endl;                 // -3，向零取整
long long big = 1000000LL * 1000000;    // 用 long long 才装得下 10^12
cout << big << endl;

