#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;

struct Student {
    string name;
    int score;
};

// 自定义比较函数：返回 true 表示 a 应该排在 b 前面
bool cmp(const Student& a, const Student& b) {
    if (a.score != b.score) return a.score > b.score;  // 分数高的在前
    return a.name < b.name;                            // 分数相同，姓名字典序小的在前
    // 注意两个元素「相等」时这里会返回 false，这正是 sort 要求的严格弱序；
    // 若把 > 写成 >=，sort 的内部逻辑会混乱，运行时可能崩溃或结果错乱
}

int main() {
    int n;
    cin >> n;

    // 一个人就是一个 Student，姓名和分数绑在一起，排序时不会被拆散
    vector<Student> st(n);
    for (int i = 0; i < n; ++i) {
        cin >> st[i].name >> st[i].score;
    }

    // sort 需要 <algorithm>；第三个参数决定「谁排在前面」
    sort(st.begin(), st.end(), cmp);

    int rank = 1;   // 当前名次
    for (int i = 0; i < n; ++i) {
        // 与上一名分数不同 → 名次是「排在前面的人数 + 1」，而 i 正好就是前面的人数
        // 分数相同 → 名次不变，形成并列（1、2、2、4 的排法）
        if (i > 0 && st[i].score != st[i - 1].score) {
            rank = i + 1;
        }
        cout << rank << " " << st[i].name << " " << st[i].score << endl;
    }
    return 0;
}

